sp_AlterarStatusCategoriaProduto	ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION	CREATE DEFINER=`root`@`%` PROCEDURE `sp_AlterarStatusCategoriaProduto`(IN p_idCategoria INT)\nBEGIN\n\n    UPDATE CategoriaProduto\n\n    SET fAtivo = IF(fAtivo = 1, 0, 1)\n\n    WHERE idCategoriaProduto = p_idCategoria;\n\nEND	utf8mb4	utf8mb4_0900_ai_ci	utf8mb4_0900_ai_ci
